"""Resume sorting using measured poses, not the nominal placement bounds."""

import inspect
import math
import statistics


def _motion_adapter(api):
    """Accommodate common Cartesian-motion API signatures."""
    names = ("move_tcp", "move_to", "move", "move_ee", "move_linear", "movel")
    for name in names:
        fn = getattr(api, name, None)
        if not callable(fn):
            continue
        try:
            sig = inspect.signature(fn)
        except (TypeError, ValueError):
            continue

        params = sig.parameters
        fields = set(params)
        vector_name = next(
            (n for n in (
                "position", "target_position", "target", "xyz",
                "tcp_position", "pos", "p"
            ) if n in fields),
            None,
        )

        if {"x", "y", "z"} <= fields:
            mode = "xyz"
        elif vector_name:
            mode = "vector"
        else:
            continue

        supplied = {"x", "y", "z"} if mode == "xyz" else {vector_name}
        extra = {}
        supported = True
        for n, p in params.items():
            if n in supplied or p.kind in (
                inspect.Parameter.VAR_POSITIONAL,
                inspect.Parameter.VAR_KEYWORD,
            ):
                continue
            if p.default is not inspect.Parameter.empty:
                continue
            if n in ("yaw", "yaw_deg"):
                extra[n] = 0.0
            elif n in ("speed", "velocity"):
                extra[n] = 0.10
            elif n in ("duration", "seconds"):
                extra[n] = 2.0
            else:
                supported = False
                break

        if not supported:
            continue

        def move(x, y, z, fn=fn, params=params, mode=mode,
                 vector_name=vector_name, extra=extra):
            values = dict(extra)
            if mode == "xyz":
                values.update(x=float(x), y=float(y), z=float(z))
            else:
                values[vector_name] = [float(x), float(y), float(z)]

            args, kwargs = [], {}
            for n, p in params.items():
                if p.kind == inspect.Parameter.POSITIONAL_ONLY:
                    if n in values:
                        args.append(values[n])
                    elif p.default is not inspect.Parameter.empty:
                        args.append(p.default)
                elif n in values:
                    kwargs[n] = values[n]
            result = fn(*args, **kwargs)
            if result is False:
                raise RuntimeError("Cartesian motion was rejected.")
            return result

        return move

    raise RuntimeError(
        "No supported Cartesian-motion method found; refusing to guess "
        "a joint-space command or tool orientation."
    )


def _pose(api, count=5):
    samples = [api.cube_pose() for _ in range(count)]
    colours = [s[2] for s in samples]
    colour = max(set(colours), key=colours.count)
    samples = [s for s in samples if s[2] == colour]
    position = [
        statistics.median(float(s[0][i]) for s in samples)
        for i in range(3)
    ]
    if not all(math.isfinite(v) for v in position):
        raise RuntimeError("Invalid cube position.")
    if colour not in ("red", "green", "blue"):
        raise RuntimeError("Unrecognised cube colour.")
    return position, colour


def _settle(api):
    """Advance simulation time explicitly when a wait method is available."""
    wait = getattr(api, "wait", None)
    if callable(wait):
        try:
            params = inspect.signature(wait).parameters
        except (TypeError, ValueError):
            params = None
        if params is not None:
            for name in ("seconds", "duration", "dt"):
                if name in params:
                    wait(**{name: 0.5})
                    return
            for name in ("steps", "n_steps"):
                if name in params:
                    wait(**{name: 120})
                    return
            if not params:
                for _ in range(10):
                    wait()
                return

    # Bounded fallback for APIs whose calls also advance the simulation.
    for _ in range(12):
        if api.done():
            break
        api.cube_pose()


def run(api):
    if api.done():
        return

    move = _motion_adapter(api)
    api.suction(on=False)

    # The existing observations locate the blue cube near (0.563, -0.226),
    # well outside the nominal test distribution. Do not reject or clamp it.
    for attempt in range(3):
        position, colour = _pose(api, 7)
        x, y, z = position
        bin_position, _ = api.bin_pose(colour=colour)
        bx, by, rim_z = map(float, bin_position)

        # A held 40 mm cube must clear the 60 mm walls before translation.
        transit_z = max(0.18, rim_z + 0.10, z + 0.10)
        move(x, y, transit_z)

        attached = False
        # Probe both plausible pose-height conventions: top face or centre.
        # Verify attachment by measured cube motion, not the suction return.
        for step in range(15):
            contact_z = z + 0.024 - 0.002 * step
            move(x, y, contact_z)
            api.suction(on=True)

            test_z = contact_z + 0.015
            move(x, y, test_z)
            lifted, observed_colour = _pose(api, 3)

            if observed_colour == colour and lifted[2] > z + 0.008:
                attached = True
                break

            api.suction(on=False)

        if not attached:
            move(x, y, transit_z)
            continue

        move(x, y, transit_z)
        carried, carried_colour = _pose(api, 3)
        if carried_colour != colour or carried[2] <= z + 0.04:
            api.suction(on=False)
            _settle(api)
            continue

        # No yaw alignment is needed: even at 45 degrees the cube's
        # footprint is only 56.6 mm wide inside a 120 mm opening.
        move(bx, by, transit_z)

        # Enter vertically at the bin centre, then release with a small drop.
        # Keeping the cup above the rim also avoids tool/wall contact.
        release_z = rim_z + 0.020
        move(bx, by, release_z)
        api.suction(on=False)
        move(bx, by, transit_z)
        _settle(api)

        for _ in range(12):
            if api.done():
                return
            api.cube_pose()

    raise RuntimeError("Sorting was attempted, but api.done() did not confirm success.")
